import{_ as e,o as t,c as l,ae as o}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"註銷帳戶說明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/help/account-deletion.md","filePath":"v1/zh-HK/help/account-deletion.md"}'),i={name:"v1/zh-HK/help/account-deletion.md"};function r(n,a,c,h,d,p){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="註銷帳戶說明" tabindex="-1">註銷帳戶說明 <a class="header-anchor" href="#註銷帳戶說明" aria-label="Permalink to &quot;註銷帳戶說明&quot;">​</a></h1><p>註銷帳戶會清空該帳戶在雲端與本機的所有資料，請在操作前確認你已理解並接受以下影響。</p><h2 id="會發生什麼" tabindex="-1">會發生什麼 <a class="header-anchor" href="#會發生什麼" aria-label="Permalink to &quot;會發生什麼&quot;">​</a></h2><ul><li>雲端資料：清空該帳戶的雲同步資料（包括但不限於帳本、帳單、分類、標籤等）。</li><li>本機資料：清空該帳戶在當前裝置上的本機資料（包括離線資料）。</li><li>不可撤銷：註銷執行後無法恢復已刪除的資料。</li></ul><h2 id="會員訂閱是否受影響" tabindex="-1">會員訂閱是否受影響 <a class="header-anchor" href="#會員訂閱是否受影響" aria-label="Permalink to &quot;會員訂閱是否受影響&quot;">​</a></h2><p>註銷帳戶不會影響你的訂閱有效期。</p><p>如果你是付費會員，註銷後重新登入，並在 App 內點選「恢復購買」，仍可恢復會員狀態（以 App Store / Google Play 的訂閱狀態為準）。</p><h2 id="建議" tabindex="-1">建議 <a class="header-anchor" href="#建議" aria-label="Permalink to &quot;建議&quot;">​</a></h2><ul><li>如你需要保留資料，請先在 App 內完成匯出/備份（如有）。</li><li>註銷後再重新登入將視為新環境，你需要重新同步/匯入資料。</li></ul>',9)])])}const _=e(i,[["render",r]]);export{u as __pageData,_ as default};
